var n=`0502-maqluba-palestinian-style`;var t=`world-0502`;var a=`PS`;var r=`western-asia`;var l=4;var o=86;var s={en:`Maqluba Palestinian Style`,ua:`Маклюба по-палестинськи`};var g={en:`A traditional dish from Palestine, centered on chicken thigh, yellow onion, white rice, eggplant. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Палестина. Основні складники: куряче стегно, жовта цибуля, білий рис, баклажан. Домашній варіант із кількостями продуктів за етапами приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`chicken-thigh`,720,`g`],[`yellow-onion`,180,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:14,i:[[`white-rice`,350,`g`],[`eggplant`,380,`g`],[`potato`,390,`g`],[`cauliflower`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`chicken-stock`,760,`ml`],[`allspice-berries`,5,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var d={slug:n,id:t,country:`PS`,region:r,servings:4,minutes:86,title:s,text:g,steps:h};export{a as country,d as default,t as id,o as minutes,r as region,l as servings,n as slug,h as steps,g as text,s as title};